python3 - <<'PY'
import re, pathlib
tickets = {}
for p in pathlib.Path('TICKETS').glob('TCK-*.md'):
    n = int(p.stem.split('-')[1])
    first = p.read_text().splitlines()[0]
    assert first.startswith(f'# TCK-{n}: ')
    tickets[n] = first[2:]
changelog = pathlib.Path('CHANGELOG.md').read_text()
unreleased = changelog.split('## Unreleased', 1)[1].split('## 2.8.0', 1)[0]
lines = [l for l in unreleased.splitlines() if l.strip()]
expected = [f'- {tickets[n]}' for n in sorted(tickets)]
print('changelog order/titles match:', lines == expected)
if lines != expected:
    for a,b in zip(lines,expected):
        if a!=b: print(repr(a), '!=', repr(b))
# marker counts
for n in sorted(tickets):
    marker = f'# TCK-{n}'
    hits = []
    for p in pathlib.Path('fleetd').glob('*.py'):
        for i,l in enumerate(p.read_text().splitlines(),1):
            if l.startswith('def ') and l.rstrip().endswith(marker):
                hits.append(f'{p}:{i}')
    print(f'TCK-{n}: {len(hits)} marker(s)', ', '.join(hits))
PY
